// The Bluetooth restore protocol (docs/FUJIFILM-PROTOCOL.md §3.7): frames, encoders and the restore conversation against
// a camera-side fake written from the spec. Golden vectors come from the Python port (Fixtures/xapp-restore-vectors.json,
// generated by ble/fuji_ble/gatt.py) so both ports send the same bytes.
import Foundation
import Testing
@testable import DialInCamera

/// The camera side of the restore: RESTORE_REQUEST → RESTORE_STATE, setup writes checked, transfer started (1), one ack
/// per frame (seq, zero trailers, doubled final sum, declared size, same body), file received (3), applied on 03 00.
actor RestoreCameraGATT: GATTClient {
    enum Mode { case ok, busy, rejectFirstFrame, errorAtEnd, silent, earlyFinish, missingFinish, endWriteRejected }
    let mode: Mode
    var settings: Data
    private(set) var writes: [(String, Data)] = []
    private(set) var applied = 0
    private(set) var problems: [String] = []
    private var queued: [String: [Data]] = [:]
    private var armed = false
    private var receiving = false
    private var done = false
    private var partialSize: UInt32?
    private var index: UInt32?
    private var declared = 0
    private var received = Data()
    private var expect = 0

    init(settings: Data, mode: Mode = .ok) {
        self.settings = settings
        self.mode = mode
    }

    func has(_ c: String) async -> Bool { true }
    func read(_ c: String) async throws -> Data { Data() }
    func subscribe(_ c: String) async -> Bool { true }
    func drain(_ c: String) async -> [Data] { queued.removeValue(forKey: c) ?? [] }
    var isLinkUp: Bool { true }

    func nextValue(_ c: String, timeout: Duration) async -> Data? {
        guard var q = queued[c], !q.isEmpty else { return nil }
        let v = q.removeFirst()
        queued[c] = q
        return v
    }

    private func push(_ c: String, _ v: [UInt8]) { queued[c, default: []].append(Data(v)) }

    private func fail(_ why: String) {
        problems.append(why)
        receiving = false
        push(FujiBLE.fileTransactionState, [0, 0, 0xFF, 0xFF])
    }

    func write(_ c: String, _ value: Data) async throws {
        writes.append((c, value))
        let b = [UInt8](value)
        switch c {
        case FujiBLE.restoreRequest:
            guard mode != .silent else { return }
            armed = mode != .busy && value == FujiBLE.restoreRequestSettings
            push(FujiBLE.restoreState, armed ? [1, 0] : [0, 0])
        case FujiBLE.filePartialSize where armed: partialSize = LE.u32(b, 0)
        case FujiBLE.fileTransferIndex where armed: index = LE.u32(b, 0)
        case FujiBLE.fileInformation where armed:
            let info = try FileInformation.parse(value)
            guard value.count == 44, info.name == "backup.dat", partialSize == 120, index == 0 else {
                return fail("bad setup \(value.hexString) \(String(describing: partialSize)) \(String(describing: index))")
            }
            declared = info.size
            receiving = true
            received = Data()
            expect = 0
            push(FujiBLE.fileTransactionState, [1, 0, 0, 0])
        case FujiBLE.filePartialData where receiving:
            if mode == .earlyFinish { push(FujiBLE.fileTransactionState, [3, 0, 0, 0]); return }
            if mode == .rejectFirstFrame { receiving = false; throw FujiBLEError.transfer("ATT error 0x80 (simulated)") }
            guard b.count >= 8 else { return fail("short frame") }
            let seq = LE.u16(b, 0), size = Int(LE.u32(b, 2))
            guard b.count == 6 + size + 2 else { return fail("frame length \(b.count) vs size \(size)") }
            let data = Data(b[6..<(6 + size)]), trailer = LE.u16(b, 6 + size)
            if seq != FujiBLE.lastSeq {
                guard Int(seq) == expect, trailer == 0, size == 120 else { return fail("seq \(seq) size \(size) trailer \(trailer)") }
                received += data
                expect += 1
                push(FujiBLE.fileTransactionState, [2, 0, UInt8(seq & 0xFF), UInt8(seq >> 8)])
                return
            }
            let body = data.prefix(size - 2)
            received += body
            let want = UInt16(byteSum16(received))
            let inData = LE.u16([UInt8](data.suffix(2)), 0)
            guard inData == want, trailer == want else { return fail("sums \(inData) \(trailer) want \(want)") }
            guard received.count == declared else { return fail("size \(received.count) declared \(declared)") }
            let decoded = try BLEBackupPayload.decode(received, reportedSize: nil).data
            let original = try BLEBackupPayload.decode(settings, reportedSize: nil).data
            guard decoded.count >= 0x54, original.count >= 0x54,
                  decoded[0x14..<0x54] == original[0x14..<0x54] else { return fail("other body") }
            if mode == .errorAtEnd { return fail("camera refused the file (simulated)") }
            receiving = false
            done = true
            push(FujiBLE.fileTransactionState, [mode == .missingFinish ? 2 : 3, 0, 0xFF, 0xFF])
        case FujiBLE.fileTransferResult:
            if value == FujiBLE.resultEnd && mode == .endWriteRejected { throw FujiBLEError.transfer("simulated end-result rejection") }
            if value == FujiBLE.resultEnd && done { settings = received; applied += 1 }
            done = false
            armed = false
        default: break
        }
    }
}

private final class CapacityGATT: GATTClient {
    let camera: RestoreCameraGATT
    let capacity: Int
    init(camera: RestoreCameraGATT, capacity: Int) { self.camera = camera; self.capacity = capacity }
    var maximumWriteLength: Int? { get async { capacity } }
    var isLinkUp: Bool { get async { await camera.isLinkUp } }
    func has(_ c: String) async -> Bool { await camera.has(c) }
    func read(_ c: String) async throws -> Data { try await camera.read(c) }
    func write(_ c: String, _ value: Data) async throws { try await camera.write(c, value) }
    func subscribe(_ c: String) async -> Bool { await camera.subscribe(c) }
    func nextValue(_ c: String, timeout: Duration) async -> Data? { await camera.nextValue(c, timeout: timeout) }
    func drain(_ c: String) async -> [Data] { await camera.drain(c) }
}

/// A FUJIFILMX-BACKUP-shaped file (header layout as FakeCamera/make_backup_file: magic, version, model, serial).
private func backupFile(size: Int = 70_524, serial: String = "5FA12345", seed: UInt8 = 1) -> Data {
    var b = [UInt8](repeating: 0, count: size)
    for i in 0..<size { b[i] = UInt8(truncatingIfNeeded: i &* 31 &+ Int(seed)) }
    let magic = Array("FUJIFILMX-BACKUP".utf8)
    b.replaceSubrange(0..<16, with: magic)
    b.replaceSubrange(0x10..<0x14, with: Array("0100".utf8))
    let model = Array("X100VI".utf8) + [UInt8](repeating: 0, count: 0x20 - 6)
    b.replaceSubrange(0x14..<0x34, with: model)
    let s = Array(serial.utf8) + [UInt8](repeating: 0, count: 0x20 - serial.utf8.count)
    b.replaceSubrange(0x34..<0x54, with: s)
    return Data(b)
}

struct RestoreFrameVectors: Decodable {
    var data_hex: String
    var frames_hex: [String]
    var exact_multiple_hex: [String]
    var client_names: [String: String]
    struct Loc: Decodable { var lat: Double; var lon: Double; var alt: Double; var speed: Double; var epoch: Double; var hex: String }
    var location: Loc
    struct Ident: Decodable { var read_hex: String; var id: UInt32 }
    var identification: Ident
    var file_information_hex: String
}

@Suite("Bluetooth restore protocol")
struct RestoreProtocolTests {
    static func vectors() throws -> RestoreFrameVectors { try JSONDecoder().decode(RestoreFrameVectors.self, from: Fixture.data("xapp-restore-vectors.json")) }

    @Test("Capacity preflight includes the 130-byte terminal frame for an exact payload multiple")
    func capacity() async throws {
        let file = backupFile(size: 720)
        #expect(FujiBLE.restoreFrames(file).map(\.count).max() == 130)
        let small = RestoreCameraGATT(settings: file)
        await #expect(throws: FujiBLEError.self) {
            _ = try await FujiBLEFlows.restoreSettingsStandard(CapacityGATT(camera: small, capacity: 128), file: file)
        }
        #expect(await small.writes.isEmpty)
        let adequate = RestoreCameraGATT(settings: file)
        let result = try await FujiBLEFlows.restoreSettingsStandard(CapacityGATT(camera: adequate, capacity: 130), file: file)
        #expect(result.framesSent == 6)
        #expect(await adequate.applied == 1)
    }

    @Test("Restore frames, client names, location, identification match the Python port byte for byte")
    func golden() throws {
        let v = try Self.vectors()
        let data = try #require(Data(hexString: v.data_hex))
        #expect(FujiBLE.restoreFrames(data).map(\.hexString) == v.frames_hex)
        #expect(FujiBLE.restoreFrames(Data((0..<240).map { UInt8($0) })).map(\.hexString) == v.exact_multiple_hex)
        for (name, hex) in v.client_names { #expect(FujiBLE.encodeClientName(name).hexString == hex, "\(name)") }
        let loc = FujiBLE.encodeLocation(latitude: v.location.lat, longitude: v.location.lon, altitude: v.location.alt,
                                         speed: v.location.speed, time: Date(timeIntervalSince1970: v.location.epoch))
        #expect(loc.hexString == v.location.hex)
        #expect(try FujiBLE.identificationNumber(Data(hexString: v.identification.read_hex)!) == v.identification.id)
        #expect(FileInformation.build(name: FujiBLE.backupFileName, size: 70_524).hexString == v.file_information_hex)
    }

    @Test("A 70,524-byte X100VI file is 588 frames: 587 × 128 bytes, then 0xFFFF with the sum twice")
    func frameShape() {
        let f = backupFile()
        let frames = FujiBLE.restoreFrames(f)
        #expect(frames.count == 588)
        #expect(frames.dropLast().allSatisfy { $0.count == 128 && $0.suffix(2) == Data([0, 0]) })
        let last = [UInt8](frames.last!)
        #expect(LE.u16(last, 0) == 0xFFFF)
        #expect(Int(LE.u32(last, 2)) == 70_524 - 587 * 120 + 2)
        let sum = UInt16(byteSum16(f))
        #expect(LE.u16(last, last.count - 4) == sum && LE.u16(last, last.count - 2) == sum)
    }

    @Test("Restore over the standard conversation lands the file and writes 03 00 last")
    func restoreOK() async throws {
        let file = backupFile()
        let cam = RestoreCameraGATT(settings: file)
        var edited = file
        edited[0xF800 + 0x1E5] = 0x42
        let r = try await FujiBLEFlows.restoreSettingsStandard(cam, file: edited, stateTimeout: .milliseconds(10), ackTimeout: .milliseconds(10))
        #expect(r.framesSent == 588)
        #expect(r.finalState?.first == 3)
        #expect(await cam.applied == 1)
        #expect(await cam.settings == edited)
        #expect(await cam.problems.isEmpty)
        let w = await cam.writes
        #expect(w.prefix(4).map(\.0) == [FujiBLE.restoreRequest, FujiBLE.filePartialSize, FujiBLE.fileTransferIndex, FujiBLE.fileInformation])
        #expect(w.first?.1 == Data([1, 0]))
        #expect(w.last?.0 == FujiBLE.fileTransferResult && w.last?.1 == FujiBLE.resultEnd)
    }

    @Test("Premature completion, missing final state and a failed end result cannot report success",
          arguments: [RestoreCameraGATT.Mode.earlyFinish, .missingFinish, .endWriteRejected])
    func completionMustBeAcknowledged(mode: RestoreCameraGATT.Mode) async throws {
        let camera = RestoreCameraGATT(settings: backupFile(), mode: mode)
        await #expect(throws: FujiBLEError.self) {
            _ = try await FujiBLEFlows.restoreSettingsStandard(camera, file: backupFile(),
                stateTimeout: .milliseconds(10), ackTimeout: .milliseconds(10))
        }
        #expect(await camera.applied == 0)
        if mode != .endWriteRejected {
            #expect(await !camera.writes.contains { $0.0 == FujiBLE.fileTransferResult && $0.1 == FujiBLE.resultEnd })
        }
    }

    @Test("Busy camera: nothing uploaded, 02 00 written")
    func busy() async {
        let cam = RestoreCameraGATT(settings: backupFile(), mode: .busy)
        await #expect(throws: FujiBLEError.busy) {
            _ = try await FujiBLEFlows.restoreSettingsStandard(cam, file: backupFile(), stateTimeout: .milliseconds(10))
        }
        let w = await cam.writes
        #expect(!w.contains { $0.0 == FujiBLE.filePartialData })
        #expect(w.last?.1 == FujiBLE.resultCancel)
    }

    @Test("A rejected frame is reported as an incompatible file; an Error state writes 00 00; silence uploads nothing")
    func failures() async throws {
        let reject = RestoreCameraGATT(settings: backupFile(), mode: .rejectFirstFrame)
        do {
            _ = try await FujiBLEFlows.restoreSettingsStandard(reject, file: backupFile(), stateTimeout: .milliseconds(10), ackTimeout: .milliseconds(10))
            Issue.record("expected a rejection")
        } catch let e as FujiBLEError {
            #expect(e.description.contains("incompatible firmware"))
        }
        #expect(await reject.writes.last?.1 == FujiBLE.resultCancel)

        let refuse = RestoreCameraGATT(settings: backupFile(), mode: .errorAtEnd)
        await #expect(throws: FujiBLEError.self) {
            _ = try await FujiBLEFlows.restoreSettingsStandard(refuse, file: backupFile(), stateTimeout: .milliseconds(10), ackTimeout: .milliseconds(10))
        }
        #expect(await refuse.writes.last?.1 == FujiBLE.resultFail)
        #expect(await refuse.applied == 0)

        let silent = RestoreCameraGATT(settings: backupFile(), mode: .silent)
        await #expect(throws: FujiBLEError.self) {
            _ = try await FujiBLEFlows.restoreSettingsStandard(silent, file: backupFile(), stateTimeout: .milliseconds(10))
        }
        #expect(await !silent.writes.contains { $0.0 == FujiBLE.filePartialData })

        let other = RestoreCameraGATT(settings: backupFile())
        await #expect(throws: FujiBLEError.self) {
            _ = try await FujiBLEFlows.restoreSettingsStandard(other, file: backupFile(serial: "OTHER999"), stateTimeout: .milliseconds(10), ackTimeout: .milliseconds(10))
        }
        #expect(await other.applied == 0)
    }

    @Test("Secure registration reuses a saved identification number; basic reads 2a25 before the key")
    func registration() async throws {
        let secure = FakeGATT()
        let reg = try await FujiBLEFlows.register(secure, clientName: "Dial In", identificationNumber: 0x2000_1234, pause: .milliseconds(1))
        #expect(reg.identificationNumber == 0x2000_1234)
        #expect(await secure.writes.first?.1 == Data([0x34, 0x12, 0x00, 0x20]))

        let basic = FakeGATT()
        await basic.configure { g in
            g.present.remove(FujiBLE.secureStatus)
            g.present.insert(FujiBLE.pairingToken)
            g.present.insert(FujiBLE.serialNumber)
        }
        let breg = try await FujiBLEFlows.register(basic, clientName: "Dial In", token: Data([1, 2, 3, 4]))
        #expect(breg.mode == "basic")
        let steps = await basic.steps.filter { !$0.hasPrefix("subscribe") }
        #expect(Array(steps.prefix(3)) == ["read 00002a25", "write aba356eb", "write 85b9163e"])
    }

    @Test("Adverts: a registered basic body advertises only the FILE_TRANSFER service")
    func basicAdvert() {
        #expect(FujiAdvert.parse(manufacturer: nil, services: [FujiBLE.fileService.uppercased()])?.kind == .basic)
        #expect(FujiAdvert.parse(manufacturer: Data([0xD8, 0x04, 0x02, 1, 2, 3, 4]), services: [FujiBLE.fileService])?.kind == .basicPairing)
        #expect(FujiAdvert.parse(manufacturer: nil, services: []) == nil)
        // A switched-off X100VI (fw 1.10): the standby advert shape captured from an X100VI during development.
        let off = FujiAdvert.parse(manufacturer: Data([0xD8, 0x04, 0x02, 0x11, 0x22, 0x33, 0x44, 0x00]),
                                   services: [FujiBLE.basicStartupService.uppercased()])
        #expect(off?.kind == .basicStandby)
        #expect(off?.token == Data([0x11, 0x22, 0x33, 0x44]))
    }

    @Test("AP_STATE: 02 80 launching waits, 01 80 launched is up, 00 80 is not; old 01/00 still read")
    func apState() async throws {
        #expect(FujiBLE.apStateUp(Data([0x01, 0x80])) == true)
        #expect(FujiBLE.apStateUp(Data([0x02, 0x80])) == nil)
        #expect(FujiBLE.apStateUp(Data([0x00, 0x80])) == false)
        #expect(FujiBLE.apStateUp(Data([0x01])) == true)
        #expect(FujiBLE.apStateUp(Data([0x00, 0x00])) == false)
        let g = WakeGATT(password: nil, apAnswers: [Data([0x02, 0x80]), Data([0x01, 0x80])])
        _ = try await FujiWifiWake.run(g, apTimeout: .milliseconds(50))
        #expect(await g.writes.count == 1, "launching is not busy: no second launch request")
    }
}
